<?php
namespace App\Console\Commands;use Illuminate\Console\Command;use Illuminate\Support\Facades\Route;use Illuminate\Support\Facades\Schema;
class WarehouseV2ReportsControlCheckCommand extends Command{protected $signature='warehouse:v2-reports-control-check';protected $description='Validasi Reports & Control Warehouse';public function handle():int{$tables=['wh_reconciliation_runs','wh_reconciliation_exceptions','wh_report_snapshots'];$routes=['api/v1/warehouse/reports-v2/executive','api/v1/warehouse/reports-v2/operations','api/v1/warehouse/reports-v2/finance','api/v1/warehouse/reports-v2/audit','api/v1/warehouse/reports-v2/reconciliation'];$missing=array_values(array_filter($tables,fn($t)=>!Schema::hasTable($t)));$rm=array_values(array_filter($routes,fn($u)=>!collect(Route::getRoutes())->contains(fn($r)=>$r->uri()===$u)));$ok=!$missing&&!$rm;$this->table(['Check','Result'],[['Missing tables',$missing?implode(', ',$missing):'-'],['Missing routes',$rm?implode(', ',$rm):'-'],['Status',$ok?'PASSED':'FAILED']]);return$ok?self::SUCCESS:self::FAILURE;}}
